import{_ as t,o as a,c as e,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"核心理念与定位","description":"开放元数据、社区共建、结构化收录与受控分发原则。","frontmatter":{"title":"核心理念与定位","description":"开放元数据、社区共建、结构化收录与受控分发原则。","order":1,"group":"start"},"headers":[],"relativePath":"philosophy.md","filePath":"philosophy.md"}'),i={name:"philosophy.md"};function l(s,o,n,d,h,c){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="核心理念与定位" tabindex="-1">核心理念与定位 <a class="header-anchor" href="#核心理念与定位" aria-label="Permalink to &quot;核心理念与定位&quot;">​</a></h1><h2 id="开放元数据" tabindex="-1">开放元数据 <a class="header-anchor" href="#开放元数据" aria-label="Permalink to &quot;开放元数据&quot;">​</a></h2><p>MetaFusion 致力于构建开放、规范的多媒体资源与元数据共建库：</p><ul><li><strong>高度结构化</strong>：遵循 FRBR 规范，区分作品理念、具体表现、发行实体与存储载体。</li><li><strong>稳定可引用</strong>：每条实体具备固定 UUID 与版本修订历史，便于跨平台引用与元数据集成。</li><li><strong>开放互联</strong>：提供标准 REST API，支持个人应用、社区工具与 AI Agent 无缝调用。</li></ul><h2 id="社区共建与考据精神" tabindex="-1">社区共建与考据精神 <a class="header-anchor" href="#社区共建与考据精神" aria-label="Permalink to &quot;社区共建与考据精神&quot;">​</a></h2><p>词条创建与编辑遵循可追溯与可考据原则：</p><ul><li><strong>版本追溯</strong>：实体修改记录于 <code>entity_revisions</code>，支持对比历史差异与撤销变动。</li><li><strong>实体合并</strong>：针对重复收录的词条，支持通过合并流程保留关联关系与贡献历史。</li><li><strong>来源可信</strong>：鼓励在编辑时补充 <code>edit_note</code> 与参考来源 <code>source_urls</code>，提升数据准确性。</li></ul><h2 id="分层存储与流媒体优化" tabindex="-1">分层存储与流媒体优化 <a class="header-anchor" href="#分层存储与流媒体优化" aria-label="Permalink to &quot;分层存储与流媒体优化&quot;">​</a></h2><ul><li><strong>冷热分离存储</strong>：母盘原档存储于冷存储桶，预览切片与低码率流存储于热存储桶，保障传输性能。</li><li><strong>秒传去重</strong>：基于文件 SHA-256 哈希实现存储去重。</li><li><strong>多媒体处理</strong>：音视频转码生成 HLS 流、波形图及 WebP 预览，保障多终端流畅访问。</li></ul><h2 id="邀请机制" tabindex="-1">邀请机制 <a class="header-anchor" href="#邀请机制" aria-label="Permalink to &quot;邀请机制&quot;">​</a></h2><p>邀请机制用于保障社区建设质量与合规运营：</p><ul><li>维护健康的社区交流环境与高质量的元数据维护梯队；</li><li>提供清晰的邀请追溯链，保障资源贡献的可信度；</li><li>后台可动态开启或关闭公开注册与邀请码要求。</li></ul>',12)])])}const _=t(i,[["render",l]]);export{u as __pageData,_ as default};
